        public long? MinCompletedOrders { get; set; }

        /// <summary>Highest value of how many completed orders the customer has with your store within `history_window`. Lower than the minimum returns `422` on this field.</summary>
        [JsonProperty("max_completed_orders")]
        [STJS.JsonPropertyName("max_completed_orders")]
        [SellAppSchemaConstraints(Minimum = 0d, Maximum = 4294967295d)]
        public long? MaxCompletedOrders { get; set; }

        /// <summary>Lowest value of what the customer spent on completed orders within `history_window`, in integer USD cents.</summary>
