        /// <summary>Highest value of what the customer spent on completed orders within `history_window`, in integer USD cents. Lower than the minimum returns `422` on this field.</summary>
        [JsonProperty("max_lifetime_spend_cents")]
        [STJS.JsonPropertyName("max_lifetime_spend_cents")]
        [SellAppSchemaConstraints(Minimum = 0d, Maximum = 999999999999d)]
        public long? MaxLifetimeSpendCents { get; set; }

        /// <summary>Lowest value of how many other tickets the customer opened within `history_window`.</summary>
        [JsonProperty("min_prior_ticket_count")]
