        [SellAppSchemaConstraints(Minimum = 0d, Maximum = 4294967295d)]
        public long? MinPriorTicketCount { get; set; }

        /// <summary>Highest value of how many other tickets the customer opened within `history_window`. Lower than the minimum returns `422` on this field.</summary>
        [JsonProperty("max_prior_ticket_count")]
        [STJS.JsonPropertyName("max_prior_ticket_count")]
        [SellAppSchemaConstraints(Minimum = 0d, Maximum = 4294967295d)]
        public long? MaxPriorTicketCount { get; set; }

        /// <summary>Lowest value of how many support wallet refunds the customer received on other tickets within `history_window`, not counting reversed ones.</summary>
        [JsonProperty("min_prior_support_refund_count")]
        [STJS.JsonPropertyName("min_prior_support_refund_count")]
        [SellAppSchemaConstraints(Minimum = 0d, Maximum = 4294967295d)]
