        /// <summary>Highest value of how many support wallet refunds the customer received on other tickets within `history_window`, not counting reversed ones. Lower than the minimum returns `422` on this field.</summary>
        [JsonProperty("max_prior_support_refund_count")]
        [STJS.JsonPropertyName("max_prior_support_refund_count")]
        [SellAppSchemaConstraints(Minimum = 0d, Maximum = 4294967295d)]
        public long? MaxPriorSupportRefundCount { get; set; }

        /// <summary>Lowest value of the total of those support wallet refunds, in integer USD cents.</summary>
