        [JsonProperty("action_refund_cap_cents")]
        [STJS.JsonPropertyName("action_refund_cap_cents")]
        [SellAppSchemaConstraints(Minimum = 1d, Maximum = 999999999999d)]
        public long? ActionRefundCapCents { get; set; }

        /// <summary>When set, the rule closes the ticket with this outcome after replying. `null` leaves the ticket open.</summary>
        [JsonProperty("action_close_outcome")]
        [STJS.JsonPropertyName("action_close_outcome")]
        public ActionCloseOutcome? ActionCloseOutcome { get; set; }

        /// <summary>Accepted only with the value the rule already has, so a read can be sent back. Switch the rule on or off with the state endpoint; another value returns `422` on `is_active`.</summary>
        [JsonProperty("is_active")]
        [STJS.JsonPropertyName("is_active")]
