        [STJS.JsonPropertyName("clear")]
        public List<SdkUpdateSupportAutomationRuleRequestApplicationJsonClear>? Clear { get; set; }

        /// <summary>The `updated_at` you read. When the record was saved by someone else since, the change is refused with `422` on `expected_updated_at` and nothing is saved, so you never overwrite an edit you have not seen.</summary>
        [JsonProperty("expected_updated_at")]
        [STJS.JsonPropertyName("expected_updated_at")]
        public DateTimeOffset? ExpectedUpdatedAt { get; set; }

        /// <summary>Read-only. Accepted so a read can be sent back.</summary>
        [JsonProperty("id")]
        [STJS.JsonPropertyName("id")]
        public long? Id { get; set; }

        /// <summary>Accepted only with the value the rule already has. Archive or restore the rule with the state endpoint; another value returns `422` on `archived`.</summary>
        [JsonProperty("archived")]
        [STJS.JsonPropertyName("archived")]
        public bool? Archived { get; set; }

        /// <summary>Accepted only with the value the rule already has. Change the order with the reorder endpoint; another value returns `422` on `priority`.</summary>
        [JsonProperty("priority")]
        [STJS.JsonPropertyName("priority")]
        public long? Priority { get; set; }

        /// <summary>Read-only. Accepted only as `USD`.</summary>
        [JsonProperty("currency")]
        [STJS.JsonPropertyName("currency")]
        public string? Currency { get; set; }

        /// <summary>Read-only. Accepted so a read can be sent back.</summary>
        [JsonProperty("created_at")]
        [STJS.JsonPropertyName("created_at")]
        public DateTimeOffset? CreatedAt { get; set; }

        /// <summary>Read-only and not checked. Send `expected_updated_at` to refuse a stale change.</summary>
        [JsonProperty("updated_at")]
        [STJS.JsonPropertyName("updated_at")]
        public DateTimeOffset? UpdatedAt { get; set; }

    }

